Records go in as JSON objects. Two thresholds split the pairs into merge, review and distinct. The `false` criterion includes "too sparse to tell", so thin records lean toward no instead of a guess.

```python
SAME_PERSON = {
    "same_person": {
        "type": "boolean",
        "instructions": "Do records a and b describe the same person?",
        "criteria": {
            "true": "Names, affiliation and contact details are consistent with one person",
            "false": "A detail rules out one person, or the records are too sparse to tell",
        },
    }
}

def match(a, b):
    v = verdicts({"a": a, "b": b}, SAME_PERSON)["same_person"]
    p = v["probabilities"]["true"]
    if p >= 0.95 and v["confidence"] >= 0.5:
        return "merge"
    if p >= 0.5:
        return "review"
    return "distinct"

a = {"name": "J. Rivera-Lopez", "department": "Dept. of Chemistry",
     "institution": "Univ. of Example", "email": "jrivera@example.edu"}

match(a, {"name": "Julia Rivera López", "department": "Chemistry",
          "institution": "University of Example", "orcid": "0000-0002-1825-0097"})
# "merge": p(true) = 1.0

match(a, {"name": "Jorge Rivera", "department": "History",
          "institution": "Example State College", "email": "jorge.rivera@esc.example"})
# "distinct": p(true) = 0.0
```

A score question works as a reranker. Ask how well each passage answers the query, then sort by `expected_value`. Each passage is its own request, and the requests can run in parallel.

```python
from concurrent.futures import ThreadPoolExecutor

RELEVANCE = {
    "relevance": {
        "type": "score",
        "instructions": "How well does the passage answer the query?",
        "criteria": [
            "Unrelated to the query",
            "On the topic, but does not help answer it",
            "Partly answers the query",
            "Directly answers the query",
        ],
    }
}

def rerank(query, passages):
    def score(passage):
        state = {"query": query, "passage": passage}
        return verdicts(state, RELEVANCE)["relevance"]["expected_value"]

    with ThreadPoolExecutor(max_workers=8) as pool:
        scores = list(pool.map(score, passages))
    return sorted(zip(scores, passages), key=lambda pair: pair[0], reverse=True)

